from collections import deque


def maxTasksWithPills(tasks, workers, pills, strength):
    t = sorted(tasks)
    w = sorted(workers)
    n, m = len(t), len(w)

    def can(k):
        left = pills
        dq = deque()
        ptr = m - 1
        for i in range(k - 1, -1, -1):
            while ptr >= m - k and w[ptr] + strength >= t[i]:
                dq.appendleft(w[ptr])
                ptr -= 1
            if not dq:
                return False
            if dq[-1] >= t[i]:
                dq.pop()
            else:
                if left == 0:
                    return False
                left -= 1
                dq.popleft()
        return True

    lo, hi = 0, min(n, m)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
